/* @socom-skeleton body __ct__7C2DPolyFv */
C2DPoly::C2DPoly()
{
	/* 0x3016d0: the C2D defaults, placeholder vertices (w 1), UVs (Q 1), white at alpha
	 * 100, then grey 128 and (virtual) SetTrans 128 */
	m_vertex[0][0] = -6.3e-05f;
	m_vertex[0][1] = -4.6e-05f;
	m_vertex[0][2] = 0.0001f;
	m_vertex[0][3] = 1.0f;
	m_vertex[1][0] = -3e-05f;
	m_vertex[1][1] = -2e-05f;
	m_vertex[1][2] = 0.0001f;
	m_vertex[1][3] = 1.0f;
	m_vertex[2][0] = -3e-05f;
	m_vertex[2][1] = -2e-05f;
	m_vertex[2][2] = 0.0001f;
	m_vertex[2][3] = 1.0f;

	m_x = 0;
	m_y = 0;

	m_NewUV[0][0] = 0.0f;
	m_NewUV[0][1] = 0.0f;
	m_NewUV[0][2] = 1.0f;
	m_NewUV[0][3] = 0.0f;
	m_NewUV[1][0] = 1.0f;
	m_NewUV[1][1] = 1.0f;
	m_NewUV[1][2] = 1.0f;
	m_NewUV[1][3] = 0.0f;
	m_NewUV[2][0] = 1.0f;
	m_NewUV[2][1] = 1.0f;
	m_NewUV[2][2] = 1.0f;
	m_NewUV[2][3] = 0.0f;

	for (int i = 0; i < 3; i++)
	{
		m_RGB[i][0] = 255.0f;
		m_RGB[i][1] = 255.0f;
		m_RGB[i][2] = 255.0f;
		m_RGB[i][3] = 100.0f;
	}

	m_texture = NULL;
	m_isTrans = true;

	for (int i = 0; i < 3; i++)
	{
		m_RGB[i][0] = 128.0f;
		m_RGB[i][1] = 128.0f;
		m_RGB[i][2] = 128.0f;
	}

	SetTrans(128.0f);
}

